const Database = require('better-sqlite3');
const db = new Database('posts.db');

function generateSlug(title, excludePostId) {
  let baseSlug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  if (!baseSlug) {
    baseSlug = 'post';
  }

  let slug = baseSlug;
  let counter = 2;
  while (true) {
    const row = excludePostId 
      ? db.prepare('SELECT id FROM posts WHERE slug = ? AND id != ?').get(slug, excludePostId)
      : db.prepare('SELECT id FROM posts WHERE slug = ?').get(slug);

    if (!row) {
      return slug;
    }
    slug = \`\${baseSlug}-\${counter}\`;
    counter++;
  }
}

console.log('Test 1:', generateSlug('My First Post'));
console.log('Test 2:', generateSlug('My First Post', 1));
